&lt;div class=&quot;s17&quot;&gt;&lt;span class=&quot;s16&quot;&gt;•&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;s10&quot;&gt;Education:&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;s4&quot;&gt;Bachelor’s degree in Computer Science, Business, or a related field; MBA is a plus.&lt;/span&gt;&lt;/div&gt;
&lt;div class=&quot;s17&quot;&gt;&lt;span class=&quot;s16&quot;&gt;•&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;s10&quot;&gt;Ways of working:&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;s4&quot;&gt;familiarity with Agile methodologies or similar frameworks.&lt;/span&gt;&lt;/div&gt;
